dark.customCSS:
:root {
	--fs-glass: color-mix(in oklab, var(--color-gray-900) 56%, transparent);
	--fs-sidebar: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fs-bubble: color-mix(in oklab, var(--fs-accent) 12%, var(--color-gray-800) 46%);
	--fs-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--fs-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--fs-glow: color-mix(in oklab, var(--fs-accent) 45%, transparent);
	--fs-ring: color-mix(in oklab, var(--fs-accent) 16%, transparent);
	--fs-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fs-accent: oklch(0.86 0.12 120);
}

/* Summer night: glass in Open WebUI's own shapes, colored by this mode's palette and season accent. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--fs-glass) !important;
	border-color: var(--fs-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--fs-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--fs-glow) !important;
	box-shadow: 0 0 0 3px var(--fs-ring), 0 12px 40px -16px var(--fs-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--fs-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fs-line);
}
#sidebar {
	background-color: var(--fs-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--fs-line);
}
#sidebar-chat-item.selected { background-color: var(--fs-selected); }
.markdown-prose a { color: var(--fs-accent); text-decoration-color: var(--fs-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--fs-glow); }
.markdown-prose :is(h1, h2, h3) { color: var(--fs-accent); }
.markdown-prose hr { border-color: var(--fs-glow); }
html { scrollbar-color: var(--fs-line) transparent; }
::selection { background-color: var(--fs-ring); }

dark.canvasScript:
/**
 * Title: Firefly Meadow
 * Description: Fireflies blink in short bursts over swaying grass and ground mist under a crescent moon; now and then one flashes a J-shaped mating arc, a tap sends the nearest one on its own, and the cursor turns the breeze.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FIREFLY_COUNT  = 60;    // fireflies drifting over the meadow (5-120)
const DRIFT_SPEED    = 1;     // how fast the fireflies wander and the grass sways (0-3)
const REDUCED_SPEED  = 0.3;   // share of the motion kept under reduced motion (0-1)
const FLASH_LENGTH   = 0.14;  // how long a flash lasts, in seconds (0.05-0.6)
const DARK_MIN       = 1.5;   // shortest pause between flashes, in seconds (0.5-6)
const DARK_MAX       = 4.5;   // longest pause between flashes, in seconds (1-12)
const ARC_EVERY      = 8;     // average seconds between J-shaped mating arcs; 0 turns them off (0-60)
const GRASS_DENSITY  = 1;     // how thick the grass grows (0-2)
const GRASS_HEIGHT   = 0.15;  // tallest blades as a share of the screen height (0.05-0.2)
const WIND           = 0.5;   // strength of the breeze (0-2)
const CURSOR_WIND    = 0.5;   // how far the cursor turns the breeze; settles when it stops (0-2)
const MIST           = 0.5;   // ground mist along the grass line (0-1)
const MOON_PHASE     = 0.22;  // 0 new, 0.5 full (0-1)
const CENTER_CALM    = 0.8;   // how much everything thins behind the chat column (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band, in px (300-900)
const FOLLOW_THEME   = true;  // draw in the theme's colors
/* ──────────────────────────────────────────── */

const DEFAULT = { background: '#0b1018', surface: '#121a24', text: '#eef0e6', muted: '#7d8a99', accent: '#7fbf4d', accent2: '#ffd35c', accent3: '#3f7f57' };
const MAX_FLIES = 120, MAX_BLADES = 900, MAX_STARS = 140, TRAIL = 28, TAU = Math.PI * 2;
const F = (n) => new Float32Array(n);

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, colors = DEFAULT;
let grassStyle = [], flySprite = [], coreStyle = [], groundCache, mistSprite, moonSprite, moonGlow, starStyle = '#fff', trailStyle = '#fff';
let time = 0, wind = 0;
const fx = F(MAX_FLIES), fy = F(MAX_FLIES), fpx = F(MAX_FLIES), fpy = F(MAX_FLIES), fsz = F(MAX_FLIES);
const ftimer = F(MAX_FLIES), fdark = F(MAX_FLIES), fshade = new Uint8Array(MAX_FLIES);
let flies = 0;
const bx = F(MAX_BLADES), by = F(MAX_BLADES), bh = F(MAX_BLADES), bph = F(MAX_BLADES), bsp = F(MAX_BLADES), bsw = F(MAX_BLADES), blean = F(MAX_BLADES);
const groupStart = new Uint16Array(25);
const stx = F(MAX_STARS), sty = F(MAX_STARS), sts = F(MAX_STARS);
let starCount = 0;
// The J arc: one firefly at a time follows a curve whose control point dips below it, so it drops and then sweeps up
const arc = { fly: -1, t: 0, x0: 0, y0: 0, cx: 0, cy: 0, x1: 0, y1: 0, wait: ARC_EVERY * 0.5, fade: 0 };
const tx = F(TRAIL), ty = F(TRAIL);
let trailHead = 0, trailLen = 0;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
function band(x) {
	const t = Math.min(1, Math.max(0, (Math.abs(x - w / 2) / BAND_WIDTH - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
function sideX() {
	for (let i = 0; i < 6; i++) { const x = Math.random() * w; if (Math.random() < calm(x)) return x; }
	return Math.random() < 0.5 ? Math.random() * w * 0.2 : w - Math.random() * w * 0.2;
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.3, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

// ── Palette: precomputed ramps, rebuilt on theme change only ──
function applyTheme(t) {
	if (t) dark = t.dark !== false;
	colors = FOLLOW_THEME && t && t.colors ? t.colors : DEFAULT;
	const surface = hex(colors.surface), text = hex(colors.text), muted = hex(colors.muted);
	const a1 = hex(colors.accent), a2 = hex(colors.accent2), a3 = hex(colors.accent3), bg = hex(colors.background);
	const base = dark ? surface : mix(muted, text, 0.2);
	const amount = dark ? [0.14, 0.24, 0.36] : [0.3, 0.42, 0.55];
	for (let l = 0; l < 3; l++) for (let k = 0; k < 8; k++) {
		grassStyle[l * 8 + k] = rgba(mix(base, mix(a3, a1, k / 7), amount[l]), dark ? 0.45 + l * 0.22 : 0.22 + l * 0.14);
	}
	for (let k = 0; k < 8; k++) {
		const c = mix(a1, a2, 0.35 + k / 11);
		flySprite[k] = sprite(64, dark ? mix(c, [255, 255, 255], 0.15) : mix(c, text, 0.1), dark ? 0.9 : 0.75, dark ? 0.35 : 0.28);
		coreStyle[k] = rgba(dark ? mix(c, text, 0.55) : mix(c, text, 0.35), 1);
	}
	starStyle = rgba(dark ? text : muted, 1);
	trailStyle = rgba(dark ? mix(a2, text, 0.4) : mix(a2, text, 0.3), 1);
	mistSprite = sprite(128, dark ? muted : mix(muted, bg, 0.3), dark ? 0.35 : 0.25, 0.18);
	moonGlow = sprite(128, dark ? text : muted, dark ? 0.2 : 0.1, dark ? 0.06 : 0.03);
	moonSprite = new OffscreenCanvas(48, 48);
	const g = moonSprite.getContext('2d');
	g.fillStyle = rgba(dark ? text : muted, dark ? 0.9 : 0.7);
	g.beginPath(); g.arc(24, 24, 18, 0, TAU); g.fill();
	g.globalCompositeOperation = 'destination-out';
	const off = 36 * Math.min(1, Math.abs(MOON_PHASE - 0.5) * 2);
	g.beginPath(); g.arc(24 + (MOON_PHASE < 0.5 ? -1 : 1) * (36 - off), 23, 18.5, 0, TAU);
	g.fill();
	if (w) buildGround();
}

// Ground shade, cached: a soft band at the foot of the grass
function buildGround() {
	const gh = Math.max(1, Math.round(h * 0.12));
	groundCache = new OffscreenCanvas(Math.max(1, Math.round(w / 2)), Math.max(1, Math.round(gh / 2)));
	const g = groundCache.getContext('2d');
	const grad = g.createLinearGradient(0, 0, 0, groundCache.height);
	const c = dark ? mix(hex(colors.background), [0, 0, 0], 0.5) : mix(hex(colors.muted), hex(colors.accent3), 0.3);
	grad.addColorStop(0, rgba(c, 0));
	grad.addColorStop(1, rgba(c, dark ? 0.6 : 0.16));
	g.fillStyle = grad;
	g.fillRect(0, 0, groundCache.width, groundCache.height);
}

function resetFly(i) {
	fx[i] = sideX();
	fy[i] = h * (0.5 + Math.random() * 0.45);
	fpx[i] = Math.random() * TAU; fpy[i] = Math.random() * TAU;
	fsz[i] = 0.8 + Math.random() * 0.6;
	fdark[i] = DARK_MIN + Math.random() * (DARK_MAX - DARK_MIN);
	ftimer[i] = Math.random() * fdark[i];
	fshade[i] = Math.floor(Math.random() * 8);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	flies = Math.min(MAX_FLIES, Math.round(FIREFLY_COUNT * Math.max(0.5, w / 1440)));
	for (let i = 0; i < flies; i++) resetFly(i);
	// Blades grouped by layer and shade so each group strokes as one path
	const per = Math.min(Math.floor(MAX_BLADES / 24), Math.round(w / 1440 * 12 * GRASS_DENSITY));
	let n = 0;
	for (let l = 0; l < 3; l++) for (let k = 0; k < 8; k++) {
		groupStart[l * 8 + k] = n;
		for (let j = 0; j < per; j++, n++) {
			const x = sideX(), q = 1 - 0.65 * CENTER_CALM * band(x);
			bx[n] = x;
			by[n] = h + 2 - (2 - l) * h * 0.012;
			bh[n] = h * GRASS_HEIGHT * (0.35 + Math.random() * 0.65) * (0.6 + l * 0.2) * q;
			bph[n] = Math.random() * TAU; bsp[n] = 0.5 + Math.random() * 0.5; bsw[n] = 4 + Math.random() * 8;
			blean[n] = (Math.random() - 0.5) * 0.7 * bh[n];
		}
	}
	groupStart[24] = n;
	starCount = Math.min(MAX_STARS, Math.round(w * h / 12000));
	for (let i = 0; i < starCount; i++) {
		stx[i] = Math.random() * w; sty[i] = Math.random() * h * 0.5;
		sts[i] = (0.3 + Math.random() * 0.7) * calm(stx[i]);
	}
	arc.fly = -1;
	buildGround();
}

// Starts a J arc for firefly i, heading away from the chat column
function startArc(i) {
	if (i < 0 || reduced) return;
	const dir = fx[i] < w / 2 ? -1 : 1, s = Math.min(1, h / 900);
	arc.fly = i; arc.t = 0; arc.fade = 1;
	arc.x0 = fx[i]; arc.y0 = fy[i];
	arc.cx = fx[i] + dir * 50 * s; arc.cy = fy[i] + 120 * s;
	arc.x1 = fx[i] + dir * 120 * s; arc.y1 = fy[i] - 70 * s;
	trailLen = 0;
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = DRIFT_SPEED * (reduced ? REDUCED_SPEED : 1);
	time = (time + dt * motion) % 10000;
	mouse.amount = Math.max(0, mouse.amount - dt * 0.3);
	const target = Math.sin(time * 0.21) * 0.6 * WIND + (mouse.x / w - 0.5) * 2 * CURSOR_WIND * mouse.amount;
	wind += (target - wind) * Math.min(1, dt * 1.2);
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';

	// Stars and moon, dark themes only for the stars
	if (dark) {
		ctx.fillStyle = starStyle;
		for (let i = 0; i < starCount; i++) {
			ctx.globalAlpha = sts[i] * (0.35 + 0.3 * Math.sin(now / 1000 * (0.4 + (i % 7) * 0.15) + i));
			ctx.fillRect(stx[i], sty[i], 1.2, 1.2);
		}
	}
	const mx = w * 0.84, my = h * 0.17;
	ctx.globalAlpha = 1;
	ctx.drawImage(moonGlow, mx - 110, my - 110, 220, 220);
	ctx.drawImage(moonSprite, mx - 24, my - 24, 48, 48);

	ctx.globalAlpha = 1;
	if (groundCache) ctx.drawImage(groundCache, 0, h - h * 0.12, w, h * 0.12);

	// Grass, far to near, mist after the far layers
	ctx.lineCap = 'round';
	for (let l = 0; l < 3; l++) {
		ctx.lineWidth = 1 + l * 0.5;
		const lw = wind * (0.5 + l * 0.25);
		for (let k = 0; k < 8; k++) {
			const g = l * 8 + k, end = groupStart[g + 1];
			if (end === groupStart[g]) continue;
			ctx.strokeStyle = grassStyle[g];
			ctx.beginPath();
			for (let i = groupStart[g]; i < end; i++) {
				const sway = (Math.sin(time * bsp[i] + bph[i]) * 0.6 + lw) * bsw[i];
				ctx.moveTo(bx[i], by[i]);
				ctx.quadraticCurveTo(bx[i] + blean[i] * 0.15 + sway * 0.3, by[i] - bh[i] * 0.55, bx[i] + blean[i] + sway, by[i] - bh[i] + Math.abs(blean[i]) * 0.3);
			}
			ctx.stroke();
		}
		if (l === 1 && MIST > 0) {
			const breathe = 0.6 + 0.4 * Math.sin(time * 0.15);
			for (let m = 0; m < 9; m++) {
				const x = ((m / 9) * (w + 400) + time * 6 * (m % 2 ? 1 : -0.6)) % (w + 400) - 200;
				ctx.globalAlpha = MIST * breathe * calm(x) * (dark ? 0.9 : 0.7);
				ctx.drawImage(mistSprite, x - 180, h * 0.86 - 30 + (m % 3) * 12, 360, 70);
			}
			ctx.globalAlpha = 1;
		}
	}

	// Fireflies: wandering, blinking with a quick rise and a slower fade
	const glowOp = dark ? 'lighter' : 'source-over';
	const flash = FLASH_LENGTH * (reduced ? 4 : 1);
	for (let i = 0; i < flies; i++) {
		if (i !== arc.fly) {
			fpx[i] += dt * motion * (0.3 + (i % 5) * 0.06);
			fpy[i] += dt * motion * (0.25 + (i % 3) * 0.07);
			fx[i] += (Math.cos(fpx[i]) * 18 + wind * 6) * dt * motion;
			fy[i] += Math.sin(fpy[i]) * 10 * dt * motion;
			if (fx[i] < -30) fx[i] = w + 30; else if (fx[i] > w + 30) fx[i] = -30;
			if (fy[i] < h * 0.45) fy[i] += 8 * dt; else if (fy[i] > h * 0.97) fy[i] -= 8 * dt;
		}
		ftimer[i] += dt;
		if (ftimer[i] > fdark[i] + flash) { ftimer[i] = 0; fdark[i] = DARK_MIN + Math.random() * (DARK_MAX - DARK_MIN); }
		const ft = (ftimer[i] - fdark[i]) / flash;
		let b = ft < 0 ? 0 : ft < 0.3 ? ft / 0.3 : 1 - (ft - 0.3) / 0.7;
		if (i === arc.fly) b = Math.max(b, arc.t < 0.85 ? 1 : 0);
		const c = calm(fx[i]), s = fsz[i];
		ctx.globalCompositeOperation = glowOp;
		ctx.globalAlpha = (0.1 + b * 0.9) * c;
		const r = 22 * s * (0.45 + b * 0.55);
		ctx.drawImage(flySprite[fshade[i]], fx[i] - r, fy[i] - r, r * 2, r * 2);
		ctx.globalCompositeOperation = 'source-over';
		ctx.globalAlpha = (0.12 + b * 0.85) * c;
		ctx.fillStyle = coreStyle[fshade[i]];
		ctx.fillRect(fx[i] - s, fy[i] - s, s * 2, s * 2);
	}

	// The J arc and its fading streak of light
	if (ARC_EVERY > 0 && !reduced && arc.fly < 0) {
		arc.wait -= dt;
		if (arc.wait <= 0) {
			arc.wait = ARC_EVERY * (0.5 + Math.random());
			let pick = -1;
			for (let tries = 0; tries < 8 && pick < 0; tries++) { const i = Math.floor(Math.random() * flies); if (band(fx[i]) < 0.3) pick = i; }
			startArc(pick);
		}
	}
	if (arc.fly >= 0) {
		const i = arc.fly;
		arc.t += dt / 1.1;
		const u = Math.min(1, arc.t), v = 1 - u;
		fx[i] = v * v * arc.x0 + 2 * v * u * arc.cx + u * u * arc.x1;
		fy[i] = v * v * arc.y0 + 2 * v * u * arc.cy + u * u * arc.y1;
		if (arc.t < 0.85) { tx[trailHead] = fx[i]; ty[trailHead] = fy[i]; trailHead = (trailHead + 1) % TRAIL; trailLen = Math.min(TRAIL, trailLen + 1); }
		else arc.fade = Math.max(0, arc.fade - dt * 1.6);
		if (arc.t >= 1 && arc.fade <= 0) { arc.fly = -1; trailLen = 0; }
	}
	if (trailLen > 1) {
		ctx.strokeStyle = trailStyle;
		ctx.lineWidth = 2;
		const c = calm(arc.x0) * arc.fade * (dark ? 0.8 : 0.6);
		for (let k = 1; k < trailLen; k++) {
			const a = (trailHead - trailLen + k - 1 + TRAIL) % TRAIL, b = (a + 1) % TRAIL;
			ctx.globalAlpha = c * (k / trailLen);
			ctx.beginPath();
			ctx.moveTo(tx[a], ty[a]);
			ctx.lineTo(tx[b], ty[b]);
			ctx.stroke();
		}
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown': {
			// A tap sends the nearest firefly outside the chat column on a J arc
			if (arc.fly >= 0) break;
			let best = -1, bd = 1e12;
			for (let i = 0; i < flies; i++) {
				if (band(fx[i]) > 0.3) continue;
				const dx = fx[i] - d.x, dy = fy[i] - d.y, dd = dx * dx + dy * dy;
				if (dd < bd) { bd = dd; best = i; }
			}
			startArc(best);
			break;
		}
	}
};

light.customCSS:
:root {
	--fs-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--fs-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--fs-bubble: color-mix(in oklab, var(--fs-accent) 10%, var(--color-gray-100) 58%);
	--fs-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--fs-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--fs-glow: color-mix(in oklab, var(--fs-accent) 50%, transparent);
	--fs-ring: color-mix(in oklab, var(--fs-accent) 18%, transparent);
	--fs-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--fs-accent: oklch(0.5 0.13 42);
}

/* Autumn: glass in Open WebUI's own shapes, colored by this mode's palette and season accent. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--fs-glass) !important;
	border-color: var(--fs-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--fs-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--fs-glow) !important;
	box-shadow: 0 0 0 3px var(--fs-ring), 0 12px 40px -16px var(--fs-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--fs-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fs-line);
}
#sidebar {
	background-color: var(--fs-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--fs-line);
}
#sidebar-chat-item.selected { background-color: var(--fs-selected); }
.markdown-prose a { color: var(--fs-accent); text-decoration-color: var(--fs-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--fs-glow); }
.markdown-prose :is(h1, h2, h3) { color: var(--fs-accent); }
.markdown-prose hr { border-color: var(--fs-glow); }
html { scrollbar-color: var(--fs-line) transparent; }
::selection { background-color: var(--fs-ring); }

light.canvasScript:
/**
 * Title: Falling Leaves
 * Description: Autumn leaves tinted toward your theme's colors tumble down the sides of the screen on a gentle breeze, thin out behind the chat, and lift in an updraft while the cursor moves.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const LEAF_COUNT    = 46;    // leaves in the air (8-150)
const LEAF_SIZE     = 34;    // average leaf length, in px (8-60)
const FALL_SPEED    = 45;    // falling speed, in px per second (10-150)
const SWAY          = 30;    // side-to-side drift, in px per second (0-80)
const TUMBLE        = 1;     // how much leaves flip and spin (0-2)
const BREEZE        = 1;     // strength of the slow passing gusts (0-3)
const UPDRAFT       = 1;     // how hard a moving cursor lifts nearby leaves (0-3)
const OPACITY       = 1;  // leaf strength (0.15-1)
const THEME_TINT    = 0.15;   // how far the autumn hues turn toward the theme's colors (0-1)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.8;   // how much the leaves thin out behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band around the chat column, in px (300-900)
const FOLLOW_THEME  = true;  // tint the leaves with the theme's palette
const COLOR_A       = '#c8782a';  // amber leaf
const COLOR_B       = '#b4462a';  // rust leaf
const COLOR_C       = '#d2a632';  // gold leaf
const COLOR_D       = '#828c34';  // olive leaf
/* ──────────────────────────────────────────── */

const NS = 3, NC = 4, SP = 64, N = LEAF_COUNT;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true;
let calmLut = new Float32Array(1), tints = null;
const sprites = [];
const mouse = { x: -10000, y: -10000, energy: 0 };
const AUTUMN = [COLOR_A, COLOR_B, COLOR_C, COLOR_D];

const lx = new Float32Array(N), ly = new Float32Array(N), lvx = new Float32Array(N), lvy = new Float32Array(N);
const lrot = new Float32Array(N), lspin = new Float32Array(N), lbase = new Float32Array(N), ltum = new Float32Array(N), ltsp = new Float32Array(N);
const lsz = new Float32Array(N), lph = new Float32Array(N), lop = new Float32Array(N), lspr = new Uint8Array(N);

function rgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function hsl(c) {
	const r = c[0] / 255, g = c[1] / 255, b = c[2] / 255, mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = (mx + mn) / 2, d = mx - mn;
	if (!d) return [0, 0, l];
	const hh = mx === r ? (g - b) / d + (g < b ? 6 : 0) : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
	return [hh * 60, d / (1 - Math.abs(2 * l - 1)), l];
}
function fromHsl(hh, sat, l) {
	const k = (n) => (n + hh / 30) % 12, a = sat * Math.min(l, 1 - l);
	const f = (n) => 255 * (l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1)));
	return [f(0), f(8), f(4)];
}
// Turns an autumn hue part of the way toward a theme hue, keeping it rich, never muddy
function tint(leaf, theme) {
	const a = hsl(leaf), b = hsl(theme);
	let d = ((b[0] - a[0] + 540) % 360) - 180;
	if (b[1] < 0.12) d = 0;
	const lim = 70 * THEME_TINT, hh = (a[0] + Math.max(-lim, Math.min(lim, d * THEME_TINT)) + 360) % 360;
	const l = dark ? Math.max(0.5, a[2]) : Math.min(0.42, a[2]);
	return fromHsl(hh, Math.max(0.5, a[1]), l);
}
function css(c, a, m) { return 'rgba(' + Math.min(255, Math.round(c[0] * m)) + ',' + Math.min(255, Math.round(c[1] * m)) + ',' + Math.min(255, Math.round(c[2] * m)) + ',' + a + ')'; }

function leafPath(g, shape, s) {
	g.beginPath();
	if (shape === 0) {
		g.moveTo(0, -s);
		g.quadraticCurveTo(s * 0.62, -s * 0.3, s * 0.38, s * 0.35);
		g.quadraticCurveTo(s * 0.1, s * 0.75, 0, s * 0.8);
		g.quadraticCurveTo(-s * 0.1, s * 0.75, -s * 0.38, s * 0.35);
		g.quadraticCurveTo(-s * 0.62, -s * 0.3, 0, -s);
	} else if (shape === 1) {
		g.moveTo(0, -s * 0.9);
		g.bezierCurveTo(s * 0.85, -s * 0.6, s * 0.55, s * 0.3, 0, s * 0.75);
		g.bezierCurveTo(-s * 0.55, s * 0.3, -s * 0.85, -s * 0.6, 0, -s * 0.9);
	} else {
		const p = [0, -1, 0.16, -0.6, 0.48, -0.82, 0.4, -0.36, 0.86, -0.32, 0.62, 0.02, 0.78, 0.3, 0.3, 0.26, 0.14, 0.6, 0, 0.5];
		g.moveTo(0, -s);
		for (let i = 2; i < p.length; i += 2) g.lineTo(p[i] * s, p[i + 1] * s);
		for (let i = p.length - 4; i >= 0; i -= 2) g.lineTo(-p[i] * s, p[i + 1] * s);
	}
	g.closePath();
}

// One sprite per shape and tone, drawn at twice the size, rebuilt on theme change
function buildSprites() {
	const theme = tints || AUTUMN;
	for (let c = 0; c < NC; c++) {
		const col = tint(rgb(AUTUMN[c]), rgb(FOLLOW_THEME && tints ? theme[c] : AUTUMN[c]));
		const m = 1;
		for (let s = 0; s < NS; s++) {
			const k = c * NS + s, sp = sprites[k] || new OffscreenCanvas(SP, SP), g = sp.getContext('2d');
			g.setTransform(1, 0, 0, 1, 0, 0);
			g.clearRect(0, 0, SP, SP);
			g.setTransform(2, 0, 0, 2, SP / 2, SP / 2);
			const r = 14;
			leafPath(g, s, r);
			const grad = g.createLinearGradient(-r * 0.6, -r, r * 0.6, r);
			grad.addColorStop(0, css(col, 1, m * 1.15));
			grad.addColorStop(1, css(col, 1, m * 0.8));
			g.fillStyle = grad;
			g.fill();
			g.strokeStyle = css(col, 0.8, m * 0.6);
			g.lineWidth = 0.7;
			g.stroke();
			g.beginPath();
			g.moveTo(0, -r * 0.75); g.lineTo(0, r * 0.95);
			g.moveTo(0, -r * 0.2); g.lineTo(r * 0.3, -r * 0.45);
			g.moveTo(0, -r * 0.2); g.lineTo(-r * 0.3, -r * 0.45);
			g.moveTo(0, r * 0.2); g.lineTo(r * 0.32, -r * 0.02);
			g.moveTo(0, r * 0.2); g.lineTo(-r * 0.32, -r * 0.02);
			g.strokeStyle = css(col, 0.55, m * 0.55);
			g.lineWidth = 0.6;
			g.stroke();
			sprites[k] = sp;
		}
	}
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) tints = [t.colors.accent, t.colors.accent2, t.colors.accent3, t.colors.muted];
	if (ctx) buildSprites();
}

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}

function spawn(i, anywhere) {
	let x = Math.random() * w;
	for (let k = 0; k < 3 && Math.random() > calm(x); k++) x = Math.random() * w;
	lx[i] = x;
	ly[i] = anywhere ? Math.random() * h : -20 - Math.random() * 60;
	lvx[i] = 0; lvy[i] = FALL_SPEED * 0.5;
	lsz[i] = LEAF_SIZE * (0.6 + Math.random() * 0.8);
	lrot[i] = Math.random() * 6.283;
	lbase[i] = lspin[i] = (Math.random() - 0.5) * 1.6;
	ltum[i] = Math.random() * 6.283;
	ltsp[i] = 0.8 + Math.random() * 1.6;
	lph[i] = Math.random() * 6.283;
	lop[i] = 0.6 + Math.random() * 0.4;
	lspr[i] = Math.floor(Math.random() * NC * NS);
}

function size(oldW, oldH) {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	calmLut = new Float32Array((w >> 2) + 2);
	for (let i = 0; i < calmLut.length; i++) {
		const t = Math.min(1, Math.max(0, (Math.abs(i * 4 - w / 2) / BAND_WIDTH - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	if (oldW) for (let i = 0; i < N; i++) { lx[i] *= w / oldW; ly[i] *= h / oldH; }
	else for (let i = 0; i < N; i++) spawn(i, true);
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	mouse.energy *= Math.exp(-real * 2);
	ctx.clearRect(0, 0, w, h);

	const breeze = BREEZE * 22 * (Math.sin(time * 0.13) + 0.6 * Math.sin(time * 0.37 + 1.3));
	const lift = UPDRAFT * mouse.energy, base = OPACITY * (dark ? 1 : 0.9), ease = Math.min(1, dt * 1.5);
	const tumble = reduced ? 0 : TUMBLE;
	for (let i = 0; i < N; i++) {
		let tx = Math.sin(time * 0.7 + lph[i]) * SWAY + breeze, ty = FALL_SPEED * (0.7 + 0.3 * Math.sin(time * 1.3 + lph[i] * 2));
		let spin = lbase[i];
		// The updraft only blows while the cursor moves, so a parked cursor leaves the leaves alone
		if (lift > 0.02) {
			const dx = lx[i] - mouse.x, dy = ly[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < 32400 && dd > 1) {
				const dist = Math.sqrt(dd), s = (1 - dist / 180) * lift;
				ty -= s * 220; tx += (dx / dist) * s * 120;
				spin += Math.sign(lbase[i] || 1) * s * 4;
			}
		}
		lvx[i] += (tx - lvx[i]) * ease;
		lvy[i] += (ty - lvy[i]) * ease;
		lspin[i] += (spin - lspin[i]) * ease;
		lx[i] += lvx[i] * dt; ly[i] += lvy[i] * dt;
		lrot[i] += lspin[i] * TUMBLE * dt;
		ltum[i] += ltsp[i] * tumble * dt;
		if (ly[i] > h + 30 || lx[i] < -60 || lx[i] > w + 60 || ly[i] < -120) { spawn(i, false); continue; }

		const c = calm(lx[i]);
		ctx.globalAlpha = base * lop[i] * c;
		const flip = 0.25 + 0.75 * Math.abs(Math.cos(ltum[i])), k = lsz[i] / 56;
		const cs = Math.cos(lrot[i]), sn = Math.sin(lrot[i]);
		ctx.setTransform(dpr * cs * k * flip, dpr * sn * k * flip, -dpr * sn * k, dpr * cs * k, dpr * lx[i], dpr * ly[i]);
		ctx.drawImage(sprites[lspr[i]], -SP / 2, -SP / 2);
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(d.x - mouse.x, d.y - mouse.y) / 80);
			mouse.x = d.x; mouse.y = d.y;
			break;
	}
};

oled.customCSS:
:root {
	--fs-glass: color-mix(in oklab, var(--color-gray-950) 62%, transparent);
	--fs-sidebar: color-mix(in oklab, var(--color-gray-950) 76%, transparent);
	--fs-bubble: color-mix(in oklab, var(--fs-accent) 12%, var(--color-gray-800) 50%);
	--fs-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--fs-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--fs-glow: color-mix(in oklab, var(--fs-accent) 45%, transparent);
	--fs-ring: color-mix(in oklab, var(--fs-accent) 16%, transparent);
	--fs-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--fs-accent: oklch(0.85 0.06 232);
}

/* Winter night: glass in Open WebUI's own shapes, colored by this mode's palette and season accent. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--fs-glass) !important;
	border-color: var(--fs-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--fs-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--fs-glow) !important;
	box-shadow: 0 0 0 3px var(--fs-ring), 0 12px 40px -16px var(--fs-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--fs-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fs-line);
}
#sidebar {
	background-color: var(--fs-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--fs-line);
}
#sidebar-chat-item.selected { background-color: var(--fs-selected); }
.markdown-prose a { color: var(--fs-accent); text-decoration-color: var(--fs-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--fs-glow); }
.markdown-prose :is(h1, h2, h3) { color: var(--fs-accent); }
.markdown-prose hr { border-color: var(--fs-glow); }
html { scrollbar-color: var(--fs-line) transparent; }
::selection { background-color: var(--fs-ring); }

oled.canvasScript:
/**
 * Title: Snow Globe
 * Description: Snow in three depths drifts down the sides of the screen on a slow breeze, a few large flakes turn as crystals and glint, a moving cursor swirls the flakes, and a thin drift settles along the bottom edge.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FLAKE_COUNT   = 170;   // snowflakes in the air (30-500)
const FLAKE_SIZE    = 1;     // size of the flakes (0.5-2)
const FALL_SPEED    = 55;    // falling speed of a mid-depth flake, in px per second (10-160)
const BREEZE        = 1;     // strength of the slow sideways breeze (0-3)
const CRYSTALS      = 0.4;   // share of near flakes drawn as six-armed crystals (0-1)
const GLINTS        = 1;     // how often flakes catch the light (0-3)
const SWIRL         = 1;     // how strongly a moving cursor swirls the snow (0-3)
const DRIFT_HEIGHT  = 6;     // tallest the drift along the bottom grows, in px; 0 turns it off (0-12)
const OPACITY       = 0.85;  // flake strength (0.2-1)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.75;  // how much the snow thins behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band around the chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const SNOW_COLOR    = '#f2f6ff';  // flake color when not following the theme
const GLINT_COLOR   = '#bfe0ff';  // glint color when not following the theme
/* ──────────────────────────────────────────── */

const N = FLAKE_COUNT, COL = 8;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true;
let calmLut = new Float32Array(1), drift = new Float32Array(1), cap = new Float32Array(1);
let snowHex = SNOW_COLOR, glintHex = GLINT_COLOR, dot = null, crystal = null, glow = null, driftFill = '#fff', driftEdge = '#fff';
const mouse = { x: -10000, y: -10000, energy: 0 };

const fx = new Float32Array(N), fy = new Float32Array(N), fvx = new Float32Array(N), fvy = new Float32Array(N);
const fsz = new Float32Array(N), fspd = new Float32Array(N), fph = new Float32Array(N), fop = new Float32Array(N);
const frot = new Float32Array(N), fglint = new Float32Array(N), fkind = new Uint8Array(N);

function rgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
function blend(a, b, k) { return [Math.round(a[0] + (b[0] - a[0]) * k), Math.round(a[1] + (b[1] - a[1]) * k), Math.round(a[2] + (b[2] - a[2]) * k)]; }

function buildSprites() {
	const s = rgb(snowHex), g = rgb(glintHex);
	dot = dot || new OffscreenCanvas(32, 32);
	let c = dot.getContext('2d');
	c.clearRect(0, 0, 32, 32);
	let grad = c.createRadialGradient(16, 16, 0, 16, 16, 16);
	grad.addColorStop(0, rgba(s, 1)); grad.addColorStop(0.35, rgba(s, 0.85)); grad.addColorStop(0.6, rgba(s, 0.2)); grad.addColorStop(1, rgba(s, 0));
	c.fillStyle = grad; c.fillRect(0, 0, 32, 32);

	crystal = crystal || new OffscreenCanvas(48, 48);
	c = crystal.getContext('2d');
	c.setTransform(1, 0, 0, 1, 0, 0);
	c.clearRect(0, 0, 48, 48);
	c.setTransform(1, 0, 0, 1, 24, 24);
	c.strokeStyle = rgba(s, 0.95);
	c.lineWidth = 2;
	c.lineCap = 'round';
	c.beginPath();
	for (let i = 0; i < 6; i++) {
		const a = i * 1.0472, ca = Math.cos(a), sa = Math.sin(a);
		c.moveTo(0, 0); c.lineTo(ca * 20, sa * 20);
		for (let k = 0; k < 2; k++) {
			const r = 9 + k * 6, l = 6 - k * 2, bx = ca * r, by = sa * r;
			c.moveTo(bx, by); c.lineTo(bx + Math.cos(a + 0.8) * l, by + Math.sin(a + 0.8) * l);
			c.moveTo(bx, by); c.lineTo(bx + Math.cos(a - 0.8) * l, by + Math.sin(a - 0.8) * l);
		}
	}
	c.stroke();

	glow = glow || new OffscreenCanvas(32, 32);
	c = glow.getContext('2d');
	c.clearRect(0, 0, 32, 32);
	grad = c.createRadialGradient(16, 16, 0, 16, 16, 16);
	grad.addColorStop(0, rgba(blend(g, [255, 255, 255], dark ? 0.6 : 0), 1)); grad.addColorStop(0.2, rgba(g, 0.6)); grad.addColorStop(1, rgba(g, 0));
	c.fillStyle = grad; c.fillRect(0, 0, 32, 32);

	driftFill = rgba(s, dark ? 0.6 : 0.4);
	driftEdge = rgba(blend(s, [255, 255, 255], dark ? 0.6 : 0), dark ? 0.7 : 0.5);
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		// Dark themes: snow from the text color with a cool accent cast. Light themes: a soft muted blue-gray that shows on white.
		snowHex = dark ? hex(blend(rgb(c.text), rgb(c.accent3), 0.15)) : hex(blend(rgb(c.muted), rgb(c.accent3), 0.35));
		glintHex = c.accent3;
	}
	if (ctx) buildSprites();
}
function hex(c) { return '#' + ((1 << 24) | (c[0] << 16) | (c[1] << 8) | c[2]).toString(16).slice(1); }

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}

// Three depths: far flakes are small and slow, near ones large, quick and sometimes crystals
function spawn(i, anywhere) {
	let x = Math.random() * w;
	for (let k = 0; k < 3 && Math.random() > calm(x); k++) x = Math.random() * w;
	const depth = Math.random(), near = depth > 0.82;
	fx[i] = x;
	fy[i] = anywhere ? Math.random() * h : -10 - Math.random() * 40;
	fsz[i] = (depth < 0.45 ? 2.2 + Math.random() * 1.6 : near ? 6 + Math.random() * 4 : 3.8 + Math.random() * 2.4) * FLAKE_SIZE;
	fspd[i] = FALL_SPEED * (depth < 0.45 ? 0.5 : near ? 1.5 : 1) * (0.85 + Math.random() * 0.3);
	fop[i] = depth < 0.45 ? 0.45 : near ? 0.95 : 0.7;
	fvx[i] = 0; fvy[i] = fspd[i];
	fph[i] = Math.random() * 6.283;
	frot[i] = Math.random() * 6.283;
	fglint[i] = 0;
	fkind[i] = near && Math.random() < CRYSTALS ? 1 : 0;
}

function size(oldW, oldH) {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	calmLut = new Float32Array((w >> 2) + 2);
	for (let i = 0; i < calmLut.length; i++) {
		const t = Math.min(1, Math.max(0, (Math.abs(i * 4 - w / 2) / BAND_WIDTH - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	// The drift starts settled, lower behind the chat column so the message box stays clear
	const n = Math.ceil(w / COL) + 2;
	drift = new Float32Array(n); cap = new Float32Array(n);
	for (let i = 0; i < n; i++) {
		const x = i * COL;
		cap[i] = DRIFT_HEIGHT * (0.3 + 0.7 * (calm(x) - 1 + CENTER_CALM) / Math.max(0.01, CENTER_CALM)) * (0.75 + 0.25 * Math.sin(x * 0.013) * Math.sin(x * 0.0051 + 1));
		drift[i] = cap[i] * 0.9;
	}
	if (oldW) for (let i = 0; i < N; i++) { fx[i] *= w / oldW; fy[i] *= h / oldH; }
	else for (let i = 0; i < N; i++) spawn(i, true);
}

function land(x, s) {
	const c = Math.round(x / COL);
	for (let k = -1; k <= 1; k++) {
		const j = c + k;
		if (j < 0 || j >= drift.length) continue;
		drift[j] += s * 0.12 * (k ? 0.5 : 1) * Math.max(0, 1 - drift[j] / Math.max(0.01, cap[j]));
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	mouse.energy *= Math.exp(-real * 1.8);
	ctx.clearRect(0, 0, w, h);

	const breeze = BREEZE * 16 * (Math.sin(time * 0.11) + 0.5 * Math.sin(time * 0.29 + 2)), swirl = SWIRL * mouse.energy;
	const base = OPACITY * (dark ? 1 : 0.95), ease = Math.min(1, dt * 2), glintRate = reduced ? 0 : GLINTS * 0.02 * real;
	if (dark) ctx.globalCompositeOperation = 'lighter';
	for (let i = 0; i < N; i++) {
		let tx = breeze * (fspd[i] / FALL_SPEED) + Math.sin(time * 0.9 + fph[i]) * 10, ty = fspd[i];
		if (swirl > 0.02) {
			const dx = fx[i] - mouse.x, dy = fy[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < 28900 && dd > 1) {
				const dist = Math.sqrt(dd), f = (1 - dist / 170) * swirl * 260, nx = dx / dist, ny = dy / dist;
				tx += (-ny * 1.2 + nx * 0.5) * f; ty += (nx * 1.2 + ny * 0.5) * f;
			}
		}
		fvx[i] += (tx - fvx[i]) * ease; fvy[i] += (ty - fvy[i]) * ease;
		fx[i] += fvx[i] * dt; fy[i] += fvy[i] * dt;
		if (fx[i] < -12) fx[i] += w + 24; else if (fx[i] > w + 12) fx[i] -= w + 24;
		const j = Math.round(fx[i] / COL), floor = h - (j >= 0 && j < drift.length ? drift[j] : 0);
		if (fy[i] >= floor) { if (DRIFT_HEIGHT > 0) land(fx[i], fsz[i]); spawn(i, false); continue; }
		if (fy[i] < -60) fy[i] = -10;

		const c = calm(fx[i]);
		const a = base * fop[i] * c;
		if (fglint[i] > 0) fglint[i] = Math.max(0, fglint[i] - dt * 1.6);
		else if (fsz[i] > 3.5 * FLAKE_SIZE && Math.random() < glintRate) fglint[i] = 1;
		if (fglint[i] > 0) {
			const e = Math.sin(fglint[i] * 3.1416), d = fsz[i] * 4;
			ctx.globalAlpha = a * e * 0.9;
			ctx.drawImage(glow, fx[i] - d / 2, fy[i] - d / 2, d, d);
		}
		ctx.globalAlpha = a;
		if (fkind[i]) {
			frot[i] += dt * 0.5;
			const d = fsz[i] * 3, k = d / 48, cs = Math.cos(frot[i]) * k, sn = Math.sin(frot[i]) * k;
			ctx.setTransform(dpr * cs, dpr * sn, -dpr * sn, dpr * cs, dpr * fx[i], dpr * fy[i]);
			ctx.drawImage(crystal, -24, -24);
			ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
		} else {
			const d = fsz[i] * 1.8;
			ctx.drawImage(dot, fx[i] - d / 2, fy[i] - d / 2, d, d);
		}
	}
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;

	// The drift melts slowly as it fills, so it stays a low living edge rather than a band
	if (DRIFT_HEIGHT > 0) {
		const n = drift.length;
		for (let i = 0; i < n; i++) drift[i] = Math.max(0, drift[i] - dt * 0.03 * (0.3 + drift[i] / Math.max(0.01, cap[i])));
		ctx.beginPath();
		ctx.moveTo(0, h);
		ctx.lineTo(0, h - drift[0]);
		for (let i = 1; i < n - 1; i++) {
			const x0 = i * COL, mx = x0 + COL / 2;
			ctx.quadraticCurveTo(x0, h - drift[i], mx, h - (drift[i] + drift[i + 1]) / 2);
		}
		ctx.lineTo(w, h);
		ctx.closePath();
		ctx.fillStyle = driftFill;
		ctx.fill();
		ctx.beginPath();
		ctx.moveTo(0, h - drift[0]);
		for (let i = 1; i < n - 1; i++) {
			const x0 = i * COL, mx = x0 + COL / 2;
			ctx.quadraticCurveTo(x0, h - drift[i], mx, h - (drift[i] + drift[i + 1]) / 2);
		}
		ctx.strokeStyle = driftEdge;
		ctx.lineWidth = 1;
		ctx.stroke();
	}
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(d.x - mouse.x, d.y - mouse.y) / 80);
			mouse.x = d.x; mouse.y = d.y;
			break;
	}
};

her.customCSS:
:root {
	--fs-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--fs-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--fs-bubble: color-mix(in oklab, var(--fs-accent) 10%, var(--color-gray-100) 58%);
	--fs-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--fs-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--fs-glow: color-mix(in oklab, var(--fs-accent) 50%, transparent);
	--fs-ring: color-mix(in oklab, var(--fs-accent) 18%, transparent);
	--fs-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--fs-accent: oklch(0.52 0.13 355);
}

/* Spring: glass in Open WebUI's own shapes, colored by this mode's palette and season accent. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--fs-glass) !important;
	border-color: var(--fs-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--fs-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--fs-glow) !important;
	box-shadow: 0 0 0 3px var(--fs-ring), 0 12px 40px -16px var(--fs-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--fs-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--fs-line);
}
#sidebar {
	background-color: var(--fs-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--fs-line);
}
#sidebar-chat-item.selected { background-color: var(--fs-selected); }
.markdown-prose a { color: var(--fs-accent); text-decoration-color: var(--fs-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--fs-glow); }
.markdown-prose :is(h1, h2, h3) { color: var(--fs-accent); }
.markdown-prose hr { border-color: var(--fs-glow); }
html { scrollbar-color: var(--fs-line) transparent; }
::selection { background-color: var(--fs-ring); }

her.canvasScript:
/**
 * Title: Butterfly Garden
 * Description: Butterflies with wings in your theme's colors flutter along the sides of the screen leaving sparkle trails, flowers sway along the bottom edge, and a moving cursor draws the nearest butterflies after it.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const BUTTERFLIES   = 14;    // butterflies in the garden (2-40)
const BUTTERFLY_SIZE = 20;  // wing length, in px (8-36)
const FLIGHT_SPEED  = 55;    // cruising speed, in px per second (15-150)
const FLAP_SPEED    = 7;     // wing beats per second (2-14)
const SPARKLES      = 1;     // how many sparkles trail each butterfly (0-3)
const FLOWERS       = 18;    // flowers along the bottom edge (0-40)
const POLLEN        = 22;    // drifting pollen motes (0-60)
const ATTRACT       = 1;     // how strongly a moving cursor draws butterflies (0-3)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.75;  // how much the garden fades and keeps clear of the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band around the chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_A       = '#ff7fb0';  // first wing color when not following the theme
const COLOR_B       = '#9b8cff';  // second wing color
const COLOR_C       = '#ffc861';  // third wing color
const STEM_COLOR    = '#5f8f62';  // flower stem color
/* ──────────────────────────────────────────── */

const U = 44, MAX_SPARK = 220, NV = 3;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true;
let calmLut = new Float32Array(1), hexes = [COLOR_A, COLOR_B, COLOR_C, STEM_COLOR], stemStyle = STEM_COLOR;
const wings = [], stars = [], blooms = [];
let body = null, mote = null;
const mouse = { x: -10000, y: -10000, energy: 0 };

const NB = BUTTERFLIES;
const fx = new Float32Array(NB), fy = new Float32Array(NB), fvx = new Float32Array(NB), fvy = new Float32Array(NB);
const fwa = new Float32Array(NB), fph = new Float32Array(NB), fsz = new Float32Array(NB), fside = new Float32Array(NB), ftimer = new Float32Array(NB);
const fcol = new Uint8Array(NB);
const sx = new Float32Array(MAX_SPARK), sy = new Float32Array(MAX_SPARK), svy = new Float32Array(MAX_SPARK), slife = new Float32Array(MAX_SPARK), scol = new Uint8Array(MAX_SPARK);
let scount = 0;
const gx = new Float32Array(40), gh = new Float32Array(40), gph = new Float32Array(40), gsz = new Float32Array(40), gcol = new Uint8Array(40);
const px = new Float32Array(60), py = new Float32Array(60), pph = new Float32Array(60);

function rgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgba(c, a, k) {
	k = k || 0; // k > 0 lifts toward white, k < 0 darkens
	const f = (v) => Math.round(k >= 0 ? v + (255 - v) * k : v * (1 + k));
	return 'rgba(' + f(c[0]) + ',' + f(c[1]) + ',' + f(c[2]) + ',' + a + ')';
}
function sprite(wd, ht) { const s = new OffscreenCanvas(wd, ht); return [s, s.getContext('2d')]; }

function wingPath(g, ww, wh, upper) {
	const y = upper ? -0.05 * wh : 0.03 * wh;
	g.beginPath();
	g.moveTo(0, y);
	if (upper) {
		g.bezierCurveTo(0.4 * ww, y - 0.75 * wh, 1.05 * ww, y - 0.65 * wh, ww, y - 0.1 * wh);
		g.bezierCurveTo(0.9 * ww, y + 0.22 * wh, 0.3 * ww, y + 0.15 * wh, 0, y);
	} else {
		g.bezierCurveTo(0.5 * ww, y + 0.6 * wh, 0.95 * ww, y + 0.75 * wh, 0.72 * ww, y + 0.2 * wh);
		g.bezierCurveTo(0.4 * ww, y - 0.05 * wh, 0.15 * ww, y - 0.05 * wh, 0, y);
	}
	g.closePath();
}

// Right-hand wing pair per color pairing, drawn once at twice the size for crisp edges
function buildSprites() {
	const c = hexes.map(rgb);
	for (let v = 0; v < NV; v++) {
		const a = c[v], b = c[(v + 1) % 3];
		const [s, g] = sprite(U * 2.4, U * 4.4);
		g.scale(2, 2);
		g.translate(1, U * 1.2);
		for (let k = 0; k < 2; k++) {
			const upper = k === 1, ww = upper ? U : U * 0.74, wh = upper ? U * 1.3 : U * 1.0;
			wingPath(g, ww, wh, upper);
			const grad = g.createLinearGradient(0, 0, ww, upper ? -wh * 0.4 : wh * 0.4);
			grad.addColorStop(0, rgba(a, 0.95, dark ? 0.1 : -0.1));
			grad.addColorStop(0.6, rgba(b, 0.9, dark ? 0.2 : 0));
			grad.addColorStop(1, rgba(b, 0.85, dark ? 0.45 : 0.15));
			g.fillStyle = grad;
			g.fill();
			// Dark edge band with pale spots, then veins: the pattern that says butterfly
			g.save();
			g.clip();
			g.strokeStyle = rgba(a, 0.85, -0.6);
			g.lineWidth = upper ? 4.5 : 3.5;
			g.stroke();
			g.fillStyle = rgba(b, 0.9, 0.8);
			for (let i = 0; i < 4; i++) {
				const t = 0.3 + i * 0.2;
				g.beginPath();
				g.arc(ww * (upper ? 0.35 + t * 0.6 : 0.3 + t * 0.4), upper ? -wh * (0.62 - t * 0.45) : wh * (0.45 + t * 0.1), 1.1, 0, 6.2832);
				g.fill();
			}
			g.strokeStyle = rgba(a, 0.3, -0.5);
			g.lineWidth = 0.6;
			for (let i = 0; i < 3; i++) {
				g.beginPath();
				g.moveTo(0, upper ? -0.05 * wh : 0.03 * wh);
				g.lineTo(ww * (0.55 + i * 0.15), upper ? -wh * (0.55 - i * 0.2) : wh * (0.5 - i * 0.12));
				g.stroke();
			}
			g.restore();
		}
		wings[v] = s;

		const [st, sg] = sprite(24, 24);
		const sgr = sg.createRadialGradient(12, 12, 0, 12, 12, 12);
		sgr.addColorStop(0, rgba(a, 1, dark ? 0.7 : 0)); sgr.addColorStop(0.25, rgba(a, 0.5, dark ? 0.2 : 0)); sgr.addColorStop(1, rgba(a, 0, 0));
		sg.fillStyle = sgr; sg.fillRect(0, 0, 24, 24);
		sg.fillStyle = rgba(a, 0.9, dark ? 0.8 : -0.1);
		sg.beginPath(); sg.moveTo(12, 2); sg.lineTo(13.2, 10.8); sg.lineTo(22, 12); sg.lineTo(13.2, 13.2); sg.lineTo(12, 22); sg.lineTo(10.8, 13.2); sg.lineTo(2, 12); sg.lineTo(10.8, 10.8); sg.fill();
		stars[v] = st;

		const [fl, fg] = sprite(48, 48);
		fg.translate(24, 24);
		fg.fillStyle = rgba(a, dark ? 0.9 : 0.85, dark ? 0.15 : 0);
		for (let i = 0; i < 6; i++) { fg.rotate(1.0472); fg.beginPath(); fg.ellipse(0, -11, 6, 11, 0, 0, 6.2832); fg.fill(); }
		fg.fillStyle = rgba(c[(v + 2) % 3], 1, dark ? 0.5 : -0.2);
		fg.beginPath(); fg.arc(0, 0, 5.5, 0, 6.2832); fg.fill();
		blooms[v] = fl;
	}
	let g;
	[body, g] = sprite(16, U * 2.4);
	g.translate(8, U * 1.2);
	g.fillStyle = rgba(c[0], 0.95, -0.7);
	g.beginPath(); g.ellipse(0, 0, 2.6, U * 0.55, 0, 0, 6.2832); g.fill();
	g.strokeStyle = g.fillStyle; g.lineWidth = 1.2;
	g.beginPath(); g.moveTo(-1, -U * 0.5); g.quadraticCurveTo(-5, -U * 0.8, -6, -U * 1.0); g.moveTo(1, -U * 0.5); g.quadraticCurveTo(5, -U * 0.8, 6, -U * 1.0); g.stroke();
	[mote, g] = sprite(12, 12);
	const mg = g.createRadialGradient(6, 6, 0, 6, 6, 6);
	mg.addColorStop(0, rgba(c[2], 1, dark ? 0.6 : 0)); mg.addColorStop(1, rgba(c[2], 0, 0));
	g.fillStyle = mg; g.fillRect(0, 0, 12, 12);
	stemStyle = rgba(rgb(hexes[3]), dark ? 0.55 : 0.6);
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) hexes = [t.colors.accent, t.colors.accent2, t.colors.accent3, t.colors.muted];
	if (ctx) buildSprites();
}

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}
function sideX(right, reach) { return right ? w - Math.random() * w * reach : Math.random() * w * reach; }

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	calmLut = new Float32Array((w >> 2) + 2);
	for (let i = 0; i < calmLut.length; i++) {
		const t = Math.min(1, Math.max(0, (Math.abs(i * 4 - w / 2) / BAND_WIDTH - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	for (let i = 0; i < NB; i++) {
		fside[i] = i % 2; fx[i] = sideX(fside[i], 0.3); fy[i] = h * (0.1 + Math.random() * 0.7);
		fvx[i] = fvy[i] = 0; fwa[i] = Math.random() * 6.283; fph[i] = Math.random() * 6.283;
		fsz[i] = BUTTERFLY_SIZE * (0.75 + Math.random() * 0.5); fcol[i] = i % NV; ftimer[i] = Math.random() * 0.2;
	}
	for (let i = 0; i < FLOWERS; i++) {
		let x = Math.random() * w;
		for (let k = 0; k < 4 && Math.random() > calm(x) * calm(x); k++) x = Math.random() * w;
		gx[i] = x; gh[i] = 18 + Math.random() * Math.min(70, h * 0.12); gph[i] = Math.random() * 6.283;
		gsz[i] = 16 + Math.random() * 10; gcol[i] = Math.floor(Math.random() * NV);
	}
	for (let i = 0; i < POLLEN; i++) { px[i] = sideX(i % 2, 0.35); py[i] = Math.random() * h; pph[i] = Math.random() * 6.283; }
	scount = 0;
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	mouse.energy *= Math.exp(-real * 1.2);
	ctx.clearRect(0, 0, w, h);
	const base = dark ? 0.9 : 0.85;

	// Flowers: one stroke for every stem, then the blooms
	ctx.strokeStyle = stemStyle;
	ctx.lineWidth = 1.5;
	ctx.beginPath();
	for (let i = 0; i < FLOWERS; i++) {
		const s = Math.sin(time * 0.8 + gph[i]) * gh[i] * 0.08;
		ctx.moveTo(gx[i], h + 2);
		ctx.quadraticCurveTo(gx[i] + s, h - gh[i] * 0.5, gx[i] + s * 0.6, h - gh[i]);
	}
	ctx.stroke();
	for (let i = 0; i < FLOWERS; i++) {
		const s = Math.sin(time * 0.8 + gph[i]) * gh[i] * 0.08, d = gsz[i];
		ctx.globalAlpha = base * 0.85 * calm(gx[i]);
		ctx.drawImage(blooms[gcol[i]], gx[i] + s * 0.6 - d / 2, h - gh[i] - d / 2, d, d);
	}

	if (dark) ctx.globalCompositeOperation = 'lighter';
	for (let i = 0; i < POLLEN; i++) {
		py[i] -= 9 * dt;
		px[i] += Math.sin(time * 0.5 + pph[i]) * 8 * dt;
		if (py[i] < -8) { py[i] = h + 8; px[i] = sideX(i % 2, 0.35); }
		ctx.globalAlpha = (dark ? 0.5 : 0.4) * (0.6 + 0.4 * Math.sin(time * 2 + pph[i])) * calm(px[i]);
		ctx.drawImage(mote, px[i] - 4, py[i] - 4, 8, 8);
	}
	// Sparkle trails
	for (let i = 0; i < scount; i++) {
		slife[i] -= dt;
		if (slife[i] <= 0) {
			const j = --scount;
			sx[i] = sx[j]; sy[i] = sy[j]; svy[i] = svy[j]; slife[i] = slife[j]; scol[i] = scol[j];
			i--;
			continue;
		}
		sy[i] += svy[i] * dt;
		const f = slife[i] / 0.9, d = 4 + 8 * f;
		ctx.globalAlpha = (dark ? 0.85 : 0.6) * f * calm(sx[i]);
		ctx.drawImage(stars[scol[i]], sx[i] - d / 2, sy[i] - d / 2, d, d);
	}
	ctx.globalCompositeOperation = 'source-over';

	// Butterflies: wander, keep to their side of the screen, follow a moving cursor
	const pull = ATTRACT * mouse.energy, maxV = FLIGHT_SPEED * 2.2;
	for (let i = 0; i < NB; i++) {
		fwa[i] += (Math.random() - 0.5) * 6 * dt;
		let ax = (Math.cos(fwa[i]) * FLIGHT_SPEED - fvx[i]) * 1.2, ay = (Math.sin(fwa[i]) * FLIGHT_SPEED * 0.7 - fvy[i]) * 1.2;
		const c = calm(fx[i]);
		ax += (fside[i] ? 1 : -1) * (1 - c) * 160;
		if (fy[i] < h * 0.08) ay += 80; else if (fy[i] > h * 0.88) ay -= 80;
		if (fx[i] < 20) ax += 80; else if (fx[i] > w - 20) ax -= 80;
		ay += Math.sin(time * 2.2 + fph[i]) * 40;
		if (pull > 0.02) {
			const dx = mouse.x - fx[i], dy = mouse.y - fy[i], dd = dx * dx + dy * dy;
			if (dd < 62500 && dd > 400) { const dist = Math.sqrt(dd); ax += dx / dist * 220 * pull; ay += dy / dist * 220 * pull; }
		}
		fvx[i] += ax * dt; fvy[i] += ay * dt;
		const sp = Math.hypot(fvx[i], fvy[i]);
		if (sp > maxV) { fvx[i] *= maxV / sp; fvy[i] *= maxV / sp; }
		fx[i] += fvx[i] * dt; fy[i] += fvy[i] * dt;
		if (Math.abs(fx[i] - w / 2) < w * 0.1 && mouse.energy < 0.05) fside[i] = fx[i] > w / 2 ? 1 : 0;

		ftimer[i] -= dt;
		if (SPARKLES > 0 && ftimer[i] <= 0 && scount < MAX_SPARK) {
			const k = scount++;
			sx[k] = fx[i] + (Math.random() - 0.5) * 6; sy[k] = fy[i] + fsz[i] * 0.3; svy[k] = 8 + Math.random() * 12;
			slife[k] = 0.9; scol[k] = fcol[i];
			ftimer[i] = 0.12 / SPARKLES;
		}

		fph[i] += FLAP_SPEED * 6.283 * dt * (1 + pull * 0.4);
		const open = 0.18 + 0.82 * Math.abs(Math.sin(fph[i] * 0.5));
		const k = fsz[i] / U, rot = Math.max(-0.4, Math.min(0.4, fvx[i] / maxV * 0.6));
		const cs = Math.cos(rot), sn = Math.sin(rot), X = dpr * fx[i], Y = dpr * fy[i];
		ctx.globalAlpha = base * Math.max(0.3, c);
		const wsp = wings[fcol[i]], ow = k * 0.5 * open, oh = k * 0.5;
		ctx.setTransform(dpr * cs * ow, dpr * sn * ow, -dpr * sn * oh, dpr * cs * oh, X, Y);
		ctx.drawImage(wsp, -2, -U * 2.4);
		ctx.setTransform(-dpr * cs * ow, -dpr * sn * ow, -dpr * sn * oh, dpr * cs * oh, X, Y);
		ctx.drawImage(wsp, -2, -U * 2.4);
		ctx.setTransform(dpr * cs * k, dpr * sn * k, -dpr * sn * k, dpr * cs * k, X, Y);
		ctx.drawImage(body, -8, -U * 1.2);
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			buildSprites();
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(d.x - mouse.x, d.y - mouse.y) / 80);
			mouse.x = d.x; mouse.y = d.y;
			break;
	}
};
